fn put64(out:[*c]u8,pos:*usize,x:i64)void{const u:u64=@bitCast(x);for(0..8)|i|out[pos.*+i]=@truncate(u>>(i*8));pos.*+=8;}
fn emit(v:[*c]const i64,n:usize,i:usize,sel:*[6]i64,used:usize,out:[*c]u8,pos:*usize)void{if(i==n){out[pos.*]=@intCast(used);pos.*+=1;for(0..used)|j|put64(out,pos,sel[j]);return;}emit(v,n,i+1,sel,used,out,pos);sel[used]=v[i];emit(v,n,i+1,sel,used+1,out,pos);}
export fn powerset(v:[*c]const i64,n:usize,out:[*c]u8,cap:usize)i64{if(v==null or n<1 or n>7 or v[0]<0 or v[0]>6 or n!=@as(usize,@intCast(v[0]))+1)return -1;const count:usize=@intCast(v[0]);const subsets:usize=@as(usize,1)<<@intCast(count);const need=2+subsets+8*count*(subsets/2);for(1..n)|i|if(v[i]<-1000000 or v[i]>1000000)return -1;if(need>cap or out==null)return -2;out[0]=@intCast(subsets);out[1]=@intCast(subsets>>8);var selected=[_]i64{0}**6;var pos:usize=2;emit(v+1,count,0,&selected,0,out,&pos);return @intCast(need);}
